#!/bin/sh
# Generated by YDK go-http-service (env phase): make env-up
# Hand edit (task 77): pinned node image, vendored ingress manifest (no raw.githubusercontent.com),
# cached Strimzi chart, preloaded images, and ingress + Strimzi brought up in parallel.
set -eu
cd "$(dirname "$0")/.."
. scripts/env.sh
. scripts/tools.sh

require kind kubectl helm sha256sum
if kind get clusters 2>/dev/null | grep -qx "$CLUSTER"; then
  echo "env-up: kind cluster $CLUSTER already exists"
else
  kind create cluster --name "$CLUSTER" --config deploy/local/kind-config.yaml
fi
kubectl config use-context "kind-$CLUSTER"

# Preload images already in the local docker daemon (see scripts/env-images.sh); others pull in-cluster.
if command -v docker >/dev/null 2>&1; then
  for img in $ENV_IMAGES; do
    if docker image inspect "$img" >/dev/null 2>&1; then
      kind load docker-image --name "$CLUSTER" "$img"
    fi
  done
fi

# Pinned, checksummed ingress manifest and Strimzi chart.
echo "$INGRESS_NGINX_SHA256  deploy/local/ingress-nginx.yaml" | sha256sum -c - || die "checksum mismatch for ingress-nginx.yaml"
: "${STRIMZI_CHART_DIR:=$HOME/.cache/clopy-paste/strimzi-chart}"
chart="$STRIMZI_CHART_DIR/strimzi-kafka-operator-$STRIMZI_VERSION.tgz"
if [ ! -f "$chart" ]; then
  mkdir -p "$STRIMZI_CHART_DIR"
  helm pull oci://quay.io/strimzi-helm/strimzi-kafka-operator --version "$STRIMZI_VERSION" -d "$STRIMZI_CHART_DIR"
fi
echo "$STRIMZI_CHART_SHA256  $chart" | sha256sum -c - || die "checksum mismatch for $chart"

kubectl apply -f deploy/local/ingress-nginx.yaml
# worker_processes defaults to the host core count, each with its own reuseport listener. On a
# many-core host (22 under WSL) some listeners end up with no worker, and connections hashed
# to them hang forever. One shared listener and two workers avoid that. The apply above resets
# the configmap, so a re-run patches and restarts again. The rollout is awaited at the end.
kubectl -n ingress-nginx patch configmap ingress-nginx-controller --type merge \
  -p '{"data":{"reuse-port":"false","worker-processes":"2"}}'
kubectl -n ingress-nginx rollout restart deployment/ingress-nginx-controller

kubectl create namespace "$NAMESPACE" --dry-run=client -o yaml | kubectl apply -f -
helm upgrade --install strimzi-kafka-operator "$chart" --namespace "$NAMESPACE" --create-namespace
kubectl wait --for=condition=Established crd/kafkas.kafka.strimzi.io crd/kafkanodepools.kafka.strimzi.io \
  crd/kafkatopics.kafka.strimzi.io crd/kafkausers.kafka.strimzi.io --timeout=120s
kubectl apply -f deploy/local/kafka.yaml
kubectl apply -f deploy/local/kafka-topics.yaml
kubectl apply -f deploy/local/kafka-users.yaml

kubectl -n ingress-nginx rollout status deployment/ingress-nginx-controller --timeout=300s
kubectl rollout status deployment/strimzi-cluster-operator -n "$NAMESPACE" --timeout=300s
kubectl wait "kafka/$KAFKA_CLUSTER" -n "$NAMESPACE" --for=condition=Ready --timeout=600s
kubectl wait kafkauser/clopy-paste-a -n "$NAMESPACE" --for=condition=Ready --timeout=300s
password=$(kubectl get secret clopy-paste-a -n "$NAMESPACE" -o go-template='{{.data.password | base64decode}}')
kubectl create secret generic clopy-paste-a-credentials -n "$NAMESPACE" \
  --from-literal=username=clopy-paste-a --from-literal=password="$password" \
  --dry-run=client -o yaml | kubectl apply -f -
echo "env-up: ok"
